<script setup lang="ts">
import{ref}from"vue";import{onLoad,onPullDownRefresh}from"@dcloudio/uni-app";import WareState from"@/shared/components/WareState.vue";import{baseOutsourceIncomeApi,type IncomeOverview}from"../../api/base-outsource-income.api";
const month=ref(new Date().toISOString().slice(0,7)),data=ref<IncomeOverview>(),loading=ref(true),error=ref("");async function load(){loading.value=true;error.value="";try{data.value=await baseOutsourceIncomeApi.overview(month.value)}catch(e){error.value=e instanceof Error?e.message:"收益数据加载失败"}finally{loading.value=false;uni.stopPullDownRefresh()}}function move(delta:number){const[y,m]=month.value.split('-').map(Number);const d=new Date(y,m-1+delta,1);month.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;load()}const money=(v:number)=>Number(v||0).toFixed(2);onLoad(load);onPullDownRefresh(load);
</script>
<template><view class="page"><view class="month"><button @click="move(-1)">‹</button><b>{{month.replace('-','年')}}月</b><button @click="move(1)">›</button></view><WareState v-if="loading" type="loading" title="正在加载包干收益"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!data?.contracted" type="empty" title="当前未承包基地" description="当前账号未配置任何基地的外包负责人关系"/><template v-else><view class="base-line"><b>承包基地</b><text>{{data.bases.map(x=>x.name).join('、')}}</text></view><view class="summary"><view><b>{{data.summary.totalNum}}扎</b><text>月度总扎数</text></view><view><b>¥{{money(data.summary.subsidyAmount)}}</b><text>补贴收益</text></view><view><b>¥{{money(data.summary.totalIncome)}}</b><text>月度收益</text></view></view><view class="section">收益明细</view><view class="head"><text>场次/基地</text><text>基础货量</text><text>补贴货量</text><text>场次收益</text></view><WareState v-if="!data.sessions.length" type="empty" title="本月暂无收益明细"/><view v-for="row in data.sessions" :key="`${row.roundNo}-${row.baseId}`" class="row"><view><b>{{row.roundNo}}</b><small>{{row.baseName}}</small></view><text>{{row.baseVolume}}</text><text>{{row.subsidyVolume}}</text><strong>¥{{money(row.sessionIncome)}}</strong></view></template></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx 20rpx 40rpx;background:var(--wms-background)}.month{display:flex;align-items:center;justify-content:center;gap:22rpx;margin-bottom:16rpx}.month button{width:54rpx;height:54rpx;margin:0;padding:0;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;color:var(--wms-primary-700);font-size:30rpx;line-height:50rpx}.month b{min-width:150rpx;font-size:var(--wms-font-list-title);text-align:center}.base-line{display:flex;align-items:flex-start;gap:16rpx;padding:15rpx;background:#fff}.base-line b{flex:none;font-size:var(--wms-font-list-body)}.base-line text{color:var(--wms-text-secondary);font-size:var(--wms-font-list-meta);line-height:1.4}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8rpx;margin-top:10rpx}.summary view{padding:15rpx 8rpx;background:#fff;text-align:center}.summary b,.summary text{display:block}.summary b{color:var(--wms-primary-700);font-size:var(--wms-font-list-body)}.summary text{margin-top:5rpx;color:var(--wms-text-secondary);font-size:var(--wms-font-list-caption)}.section{margin:18rpx 2rpx 10rpx;font-size:var(--wms-font-list-title);font-weight:700}.head,.row{display:grid;grid-template-columns:1.25fr .75fr .75fr .9fr;align-items:center;gap:8rpx}.head{padding:12rpx;background:var(--wms-primary-700);color:#fff;font-size:var(--wms-font-list-meta);font-weight:650}.row{min-height:72rpx;margin-top:6rpx;padding:8rpx 12rpx;background:#fff;font-size:var(--wms-font-list-meta);line-height:var(--wms-line-list)}.row b,.row small{display:block}.row b{font-size:var(--wms-font-list-body)}.row small{color:var(--wms-text-secondary);font-size:var(--wms-font-list-caption)}.row strong{color:var(--wms-danger)}</style>
